INSERT INTO scholarship (name, provider, description, amount, application_url, min_age, max_age, required_gender, eligible_region, required_military_status, max_income_bracket, min_gpa, requires_disability, foreigner_eligibility, grade_level, major, affiliated_institution, min_credits, admission_score_condition, headcount, application_period, eligible_university, eligible_college, required_enrollment_status, min_grade, max_grade, required_degree_level, category_l1, category_l2) VALUES
('레인보우장학금', '한남대학교', '학생경력마일리지 점수를 7단계(빨/주/노/초/파/남/보)로 나눠 차등 지급(연 15만~85만원, 학년별 점수 기준 다름). 어학성적 최저기준 충족 필요. 마일리지·어학점수 혼합조건이라 구조화된 필드로 매칭 불가.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'activity_merit'),
('진리장학금', '한남대학교', '수시 학생부교과전형 환산총점 상위 3명 대상. 등록금 전액+학기당 도서비 200만원. 평점평균 3.70 이상 유지 시 4년간 지속.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'academic_merit'),
('자유장학금', '한남대학교', '수시 학생부교과전형 환산총점 상위 6명 대상(진리장학금 다음 순위). 등록금 전액+도서비 지원.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'academic_merit'),
('인돈장학금', '한남대학교', '단과대학·독립학부별 수석합격자 대상. 등록금 전액+학기당 도서비 100만원. 평점평균 3.70 이상 유지 시 2년간 지속.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'academic_merit'),
('청림장학금', '한남대학교', '모집단위(학과)별 우수합격자 대상. 수석은 등록금 전액, 차석은 등록금 50% 지급.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'academic_merit'),
('성적우수장학금(한남대)', '한남대학교', '정규학기 재학생, 직전학기 평점평균 2.0 이상·15학점 이상 취득자 대상(졸업학기는 12학점 이상). 학부(과)·전공·학년별 재학생의 12% 이내 선발.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, 2.0, NULL, NULL, NULL, NULL, NULL, '15학점 이상(졸업학기 12학점 이상)', NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'academic_merit'),
('한남드림장학금', '한남대학교', '기초생활수급자·차상위계층 및 기타 경제사정 곤란자 대상. 예산범위 내 등록금 선감면 지급.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'welfare_living'),
('희망드림장학금', '한남대학교', '평소 품행이 단정하고 모범이 되는 재학생 중 경제적 사정으로 학업보조가 필요한 학생 대상. 직전학기 평점평균 2.0 이상·15학점 이상 취득자. 100만원(등록금 범위 내) 지급.', 1000000, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, 2.0, NULL, NULL, NULL, NULL, NULL, '15학점 이상', NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'welfare_living'),
('보람장학금', '한남대학교', '학교가 인정하는 기관·시설에서 학기당 130시간 이상 봉사활동을 한 학생 대상. 학기당 50만원 지급.', 500000, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'activity_merit'),
('면학장학금(한남대)', '한남대학교', '본인 또는 부모가 장애인(3급 이내)이며 성적이 우수한 학생 대상(입학 후 2번째 학기부터). 평점평균 3.70 이상(장애학생 본인은 3.0 이상)은 등록금 40%, 평점평균 3.50~3.70 미만(장애학생 본인은 2.0~3.0 미만)은 등록금 30% 지원. "본인 또는 부모의 장애"라는 OR 조건이라 requires_disability 하나로 표현 불가.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
('튜터장학금', '한남대학교', '3·4학년 중 전체 성적 우수자 또는 운영교과목 기수강 성적우수자(평점평균 3.8 이상)가 튜터로 선발된 경우 지급. 70만원(우수튜터 선정 시 20만원 추가).', 700000, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, 3.8, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'activity_merit'),
('어학인재장학금(한남대)', '한남대학교', '어학 성적 우수 신입생 대상. 시험 종류·점수 조건이라 현재 시스템 필드로는 매칭 불가. 장학팀 홈페이지에 개별 상세페이지가 없어 구체적 금액·세부조건은 미확인 — 이름 기준 대상만 기재.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'academic_merit'),
